-- 자동 생성 파일: tools/gen_seed.py (시드 20261107). 손으로 고치지 말고 스크립트를 고친 뒤 다시 만든다.
-- 모든 값은 가짜다: 이름 「성+가짜+번호」, 전화 010-0000-xxxx, 메일 *.example, 지어낸 주소. 비밀번호는 모두 daon-pass-1!
-- 고객 40명 · 주문 300건 · 상품 30개 · 쿠폰 5종. 번호 대응표: seed/README.md

-- EverShop(PostgreSQL). 표는 앱이 처음 뜰 때 만든다(migration). 그다음 daon/stack.py가 이 파일을 한 번 넣는다.
-- 이벤트 트리거(주문 생성 메일 등)가 300번 돌지 않게 이 세션만 트리거를 끈다.
BEGIN;
SET LOCAL session_replication_role = replica;

-- 고객: customer_id = Spring 회원 id, 메일 = <username>@daon.example, 포인트는 meta_data.points

-- 상품: product_id = Spring 상품 id(201~230), sku = DAON-P<id>
-- 상품 주소(/daon-p201). 보통은 앱의 상품 생성 이벤트가 만들지만 이 세션은 트리거를 껐으므로 직접 넣는다

-- 쿠폰: Spring 쿠폰 id 101~105 = coupon_id, 코드는 sms_coupon.code와 같다

-- 주문: order_id = Spring 주문 id(9001~9300), order_number = Spring order_sn. 배송지 order_address_id = 주문 id

-- 다음 번호가 시드 뒤에서 이어지게(앱이 새로 만드는 고객·주문)
SELECT setval(pg_get_serial_sequence('"customer"', 'customer_id'), (SELECT max(customer_id) FROM "customer"));
SELECT setval(pg_get_serial_sequence('"customer_address"', 'customer_address_id'), (SELECT max(customer_address_id) FROM "customer_address"));
SELECT setval(pg_get_serial_sequence('"product"', 'product_id'), (SELECT max(product_id) FROM "product"));
SELECT setval(pg_get_serial_sequence('"coupon"', 'coupon_id'), (SELECT max(coupon_id) FROM "coupon"));
SELECT setval(pg_get_serial_sequence('"order"', 'order_id'), (SELECT max(order_id) FROM "order"));
SELECT setval(pg_get_serial_sequence('"order_address"', 'order_address_id'), (SELECT max(order_address_id) FROM "order_address"));
SELECT setval(pg_get_serial_sequence('"order_item"', 'order_item_id'), (SELECT max(order_item_id) FROM "order_item"));
COMMIT;
